def text(lines, **repl):
    """TStrings.Text after SQL[i] := value assignments (repl keys are i<index>)."""
    L = list(lines)
    for k, v in repl.items():
        L[int(k[1:])] = v
    return "\r\n".join(L) + "\r\n"

